#!/usr/bin/env bash
# Publishes this project's latest GitHub release to the pacman and Pacstall repositories. Settings
# are in package.conf beside this script. Generated by the tlu-pkgs-repo skill.
#
# Usage: sync.sh [--no-publish] [--force]
#   --no-publish  Build and sign in a temporary directory, print it, and change nothing remote.
#   --force       Rebuild even if versions/ in the repository already records the latest release.
#
# It exits quietly when nothing changed, so it is safe to run from cron. The version is committed
# last, so a run that fails halfway is retried by the next one.
#
# Environment:
#   PKGS_NOTIFY_CMD   Command run with a message when a run fails, such as a notification script.
set -euo pipefail

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=/dev/null
source "$HERE/package.conf"
ARCH_IMAGE=docker.io/library/archlinux:latest
PACMAN_RELEASE=x86_64
LOCK=/tmp/q0wkp-pkgs.lock

GH_TOKEN=$(gh auth token -u "$GH_ACCOUNT")
export GH_TOKEN

publish=true
force=false
for arg in "$@"; do
  case $arg in
    --no-publish) publish=false ;;
    --force) force=true ;;
    *) echo "unknown argument: $arg" >&2; exit 2 ;;
  esac
done

work=$(mktemp -d "${TMPDIR:-/tmp}/pkgs-$NAME.XXXXXX")
pkgs=$work/pkgs
repo_dir=$work/repo
mkdir -p "$repo_dir"

on_exit() {
  local status=$?
  if [ "$status" -ne 0 ] && [ -n "${PKGS_NOTIFY_CMD:-}" ]; then
    $PKGS_NOTIFY_CMD "pkgs sync of $NAME failed, exit $status" || true
  fi
  if $publish || [ "$status" -ne 0 ] || [ ! -e "$repo_dir/$PACMAN_REPO.db" ]; then
    rm -rf "$work"
  fi
}
trap on_exit EXIT

log() { echo "$(date -u +%FT%TZ) $NAME: $*"; }

# Like gh api, but returns 2 for a 404 and 1 for any other failure. Callers must tell them apart:
# a failed request that passed for a missing one would start a new database over the shared one.
gh_get() { # endpoint jq-filter
  if gh api "$1" --jq "$2" 2> "$work/gh.err"; then return 0; fi
  if grep -q 'HTTP 404' "$work/gh.err"; then return 2; fi
  cat "$work/gh.err" >&2
  return 1
}

# The pacman database and the git history are shared with every other project, so only one sync
# on this machine touches them at a time.
exec 9> "$LOCK"
flock 9

# Fills @@KEY@@ placeholders. Later steps source the result, so it must come out complete.
render() { # template output
  local script=() key
  for key in "${!values[@]}"; do script+=(-e "s#@@$key@@#${values[$key]}#g"); done
  mkdir -p "$(dirname "$2")"
  sed "${script[@]}" "$1" > "$2"
  if grep -q '@@' "$2"; then
    echo "unfilled placeholder in $2" >&2
    exit 1
  fi
}

# Writes .SRCINFO from the rendered pacscript, which came from this project, not from a download.
write_srcinfo() { # pacscript output
  (
    set +eu
    # shellcheck source=/dev/null
    source "$1"
    printf 'pkgbase = %s\n' "$pkgname"
    for var in gives pkgver pkgrel pkgdesc url; do
      [ -z "${!var:-}" ] || printf '\t%s = %s\n' "$var" "${!var}"
    done
    for var in arch maintainer depends makedepends optdepends pacdeps conflicts breaks replaces \
      source sha256sums source_amd64 sha256sums_amd64 source_arm64 sha256sums_arm64; do
      declare -n list=$var 2>/dev/null || continue
      for item in "${list[@]}"; do printf '\t%s = %s\n' "$var" "$item"; done
      unset -n list
    done
    printf '\npkgname = %s\n' "$pkgname"
  ) > "$2"
}

# Without a terminal, gpg-agent could otherwise open a passphrase dialog nobody answers, and the
# run would hang while holding the lock.
sign() {
  local prompt=()
  [ -t 0 ] || prompt=(--pinentry-mode error)
  gpg --batch "${prompt[@]}" --yes --quiet --detach-sign --no-armor \
    -u "$(cat "$pkgs/keys/fingerprint")" -o "$1.sig" "$1"
}

# Runs makepkg in an Arch container. makepkg refuses to run as root, and root in a rootless
# container is this user, so it builds as a throwaway user with sudo for dependencies. The image
# is refreshed because an old one's keyring rejects current packages.
build_arch_package() {
  local dir=$work/build file
  mkdir -p "$dir"
  cp "$pkgs/arch/$PACMAN_PACKAGE/PKGBUILD" "$dir/"
  for file in "${downloads[@]}"; do cp "$file" "$dir/"; done
  podman run --rm --pull=newer --security-opt label=disable -v "$dir:/build" "$ARCH_IMAGE" bash -euc '
    pacman -Syu --noconfirm --needed base-devel >/dev/null
    useradd -m builder
    echo "builder ALL=(ALL) NOPASSWD: ALL" > /etc/sudoers.d/builder
    chown -R builder /build
    cd /build
    sudo -u builder makepkg --syncdeps --force --noconfirm 2>&1 | tail -2
    chown -R root:root /build'
  mv "$dir"/*.pkg.tar.zst "$repo_dir/"
}

# Adds the package to the existing database, so every other project's packages stay listed.
update_pacman_repo() {
  local kind assets="" status=0
  sign "$package"
  assets=$(gh_get "repos/$PKGS_REPO/releases/tags/$PACMAN_RELEASE" '.assets[].name') || status=$?
  [ "$status" -ne 1 ] || exit 1
  # gh deletes an asset before re-uploading it, so a failed upload can leave packages without a
  # database. Starting a new one would drop every other project.
  if grep -q '\.pkg\.tar\.zst$' <<<"$assets" && ! grep -qx "$PACMAN_REPO.db" <<<"$assets"; then
    echo "$PKGS_REPO has packages but no $PACMAN_REPO.db, restore it before syncing" >&2
    exit 1
  fi
  for kind in db files; do
    if grep -qx "$PACMAN_REPO.$kind" <<<"$assets"; then
      gh release download "$PACMAN_RELEASE" -R "$PKGS_REPO" -D "$work" -p "$PACMAN_REPO.$kind"
      mv "$work/$PACMAN_REPO.$kind" "$repo_dir/$PACMAN_REPO.$kind.tar.gz"
    fi
  done
  podman run --rm --security-opt label=disable -v "$repo_dir:/repo" "$ARCH_IMAGE" bash -euc '
    cd /repo
    repo-add -q '"$PACMAN_REPO"'.db.tar.gz *.pkg.tar.zst'
  # repo-add leaves symlinks, and a release can only hold real files.
  for kind in db files; do
    cp --remove-destination "$repo_dir/$PACMAN_REPO.$kind.tar.gz" "$repo_dir/$PACMAN_REPO.$kind"
    sign "$repo_dir/$PACMAN_REPO.$kind"
  done
}

update_pacstall_index() {
  local dir
  (
    cd "$pkgs"
    ls -1 packages > packagelist
    {
      printf '### Auto-generated by sync.sh\n'
      for dir in packages/*/; do
        printf -- '---\n'
        cat "$dir.SRCINFO"
      done
    } > srclist
  )
}

add_to_readme_list() {
  grep -qiE "^\| $NAME \|" "$pkgs/README.md" && return 0
  awk -v row="| $NAME | \`$PACMAN_PACKAGE\` | \`$PACSTALL_PACKAGE\` | $README_NOTES |" '
    /^\|/ { in_table = 1 }
    in_table && !/^\|/ { print row; in_table = 0; done = 1 }
    { print }
    END { if (in_table && !done) print row }' "$pkgs/README.md" > "$work/README.md"
  mv "$work/README.md" "$pkgs/README.md"
}

publish_pacman_repo() {
  local base asset name_pattern
  gh release view "$PACMAN_RELEASE" -R "$PKGS_REPO" >/dev/null 2>&1 \
    || gh release create "$PACMAN_RELEASE" -R "$PKGS_REPO" --title "pacman repository ($PACMAN_RELEASE)" \
      --notes "Package files for the pacman repository. See the README." --latest=false
  # The package goes first, so the database never names a file that isn't there yet.
  gh release upload "$PACMAN_RELEASE" -R "$PKGS_REPO" --clobber "$package" "$package.sig"
  gh release upload "$PACMAN_RELEASE" -R "$PKGS_REPO" --clobber \
    "$repo_dir/$PACMAN_REPO.db" "$repo_dir/$PACMAN_REPO.db.sig" \
    "$repo_dir/$PACMAN_REPO.files" "$repo_dir/$PACMAN_REPO.files.sig"
  # The old version is no longer in the database, so its files can go.
  base=$(basename "$package")
  name_pattern=$(sed 's/[.+]/\\&/g' <<<"$PACMAN_PACKAGE")
  while read -r asset; do
    [ -n "$asset" ] || continue
    case $asset in
      "$base" | "$base.sig") ;;
      *) gh release delete-asset "$PACMAN_RELEASE" "$asset" -R "$PKGS_REPO" --yes ;;
    esac
  done < <(gh release view "$PACMAN_RELEASE" -R "$PKGS_REPO" --json assets --jq '.assets[].name' \
    | grep -E "^$name_pattern-[^-]+-[^-]+-[^-]+\.pkg\.tar\.zst(\.sig)?$" || true)
}

record_and_push() {
  # The helper reads the token from the environment, which keeps it out of the process list.
  local git_auth=(-c credential.helper=
    -c 'credential.helper=!f() { echo username=x-access-token; echo "password=$GH_TOKEN"; }; f')
  echo "$tag" > "$pkgs/versions/$NAME"
  (
    cd "$pkgs"
    git add arch packages packagelist srclist versions README.md
    # A forced rerun of the same release can leave nothing to commit.
    git diff --cached --quiet || git commit -q -m "chore: update $NAME to $tag"
    git "${git_auth[@]}" push -q origin HEAD:main \
      || { git "${git_auth[@]}" pull -q --rebase origin main \
        && git "${git_auth[@]}" push -q origin HEAD:main; }
  )
}

status=0
tag=$(gh_get "repos/$SOURCE_REPO/releases/latest" .tag_name) || status=$?
[ "$status" -ne 1 ] || exit 1
if [ "$status" -eq 2 ]; then
  log "no release yet, skipping"
  exit 0
fi
git clone -q --depth 1 "https://github.com/$PKGS_REPO.git" "$pkgs"
if [ ! -f "$pkgs/keys/fingerprint" ]; then
  echo "$PKGS_REPO has not been initialized" >&2
  exit 1
fi
if ! $force && [ "$tag" = "$(cat "$pkgs/versions/$NAME" 2>/dev/null || true)" ]; then exit 0; fi

# Fails here, before the build, if the key can't sign.
sign "$pkgs/keys/fingerprint"
rm "$pkgs/keys/fingerprint.sig"

version=${tag#v}
declare -A values=([TAG]=$tag [VERSION]=$version [PKGVER]=${version//[^0-9A-Za-z._]/.})
declare -a downloads=()
release_assets=$(gh api "repos/$SOURCE_REPO/releases/tags/$tag" --jq '.assets[].name')
mkdir -p "$work/assets"

for entry in "${ASSETS[@]}"; do
  key=${entry%%=*}
  pattern=${entry#*=}
  pattern=${pattern//\{version\}/$version}
  asset=""
  while read -r candidate; do
    # shellcheck disable=SC2254
    case $candidate in $pattern) asset=$candidate; break ;; esac
  done <<< "$release_assets"
  if [ -z "$asset" ]; then
    log "$tag has no asset matching $pattern, skipping"
    exit 0
  fi
  gh release download "$tag" -R "$SOURCE_REPO" -D "$work/assets" -p "$asset"
  values[ASSET_$key]=$asset
  values[SHA256_$key]=$(sha256sum "$work/assets/$asset" | cut -d' ' -f1)
  downloads+=("$work/assets/$asset")
done
if [ "$SOURCE_TARBALL" = true ]; then
  source_file=$work/assets/$NAME-$version.tar.gz
  curl -fsSL -o "$source_file" "https://github.com/$SOURCE_REPO/archive/refs/tags/$tag.tar.gz"
  values[SHA256_SOURCE]=$(sha256sum "$source_file" | cut -d' ' -f1)
  downloads+=("$source_file")
fi
log "$tag"

render "$HERE/$PACSTALL_PACKAGE.pacscript.in" "$pkgs/packages/$PACSTALL_PACKAGE/$PACSTALL_PACKAGE.pacscript"
write_srcinfo "$pkgs/packages/$PACSTALL_PACKAGE/$PACSTALL_PACKAGE.pacscript" \
  "$pkgs/packages/$PACSTALL_PACKAGE/.SRCINFO"

if [ "$ARCH_MODE" = build ]; then
  render "$HERE/PKGBUILD.in" "$pkgs/arch/$PACMAN_PACKAGE/PKGBUILD"
  build_arch_package
else
  cp "$work/assets/${values[ASSET_PKG]}" "$repo_dir/"
fi

packages=("$repo_dir"/*.pkg.tar.zst)
if [ ${#packages[@]} -ne 1 ]; then
  echo "expected one package, got: ${packages[*]}" >&2
  exit 1
fi
package=${packages[0]}

update_pacman_repo
update_pacstall_index
add_to_readme_list

if ! $publish; then
  echo "built in $work, nothing published:"
  ls -l "$repo_dir"
  exit 0
fi
publish_pacman_repo
record_and_push
log "published $tag"
